210→    }
211→  }, [refreshTables, t, sessionId]);
212→
213→  const handleDeleteAll = useCallback(async () => {
214→    if (tables.length === 0) return;
215→    if (!confirm(t('deleteAllTablesConfirm'))) return;
216→    try {
217→      for (const table of tables) {
218→        const response = await fetch(`/api/tables/${encodeURIComponent(table.name)}`, {
219→          method: 'DELETE',
220→          headers: { 'X-Session-ID': sessionId },
221→        });
222→        if (!response.ok) throw new Error('Failed to delete table');
223→      }
224→      await refreshTables();
225→    } catch (e) {
226→      setError(e instanceof Error ? e.message : 'Failed to delete tables');
227→    }
228→  }, [tables, refreshTables, t, sessionId]);
229→
230→  const appClass = [
231→    'app',
232→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
233→  ].filter(Boolean).join(' ');
234→
235→  const themeIcon = theme === 'dark' ? (
236→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
237→      <circle cx="12" cy="12" r="5" />
238→      <line x1="12" y1="1" x2="12" y2="3" />
239→      <line x1="12" y1="21" x2="12" y2="23" />
240→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
241→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
242→      <line x1="1" y1="12" x2="3" y2="12" />
243→      <line x1="21" y1="12" x2="23" y2="12" />
244→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
245→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
246→    </svg>
247→  ) : (
248→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
249→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
250→    </svg>
251→  );
252→
253→  return (
